contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: depositor is the address that will call c.Deposit (must be msg.sender for c),
    // amount is the ether value to send with the deposit.
    // We perform Deposit by calling c.Deposit from this contract, so the depositor is address(this).
    // The rule: balances[address(this)] after deposit equals old + amount.
    function runTest(uint amount) public payable {
        require(msg.value == amount, "supply exactly amount as msg.value");
        // read old balance for this caller as stored in c
        uint oldBal = c.balances(address(this));

        // perform deposit on c (this contract is msg.sender for c)
        c.Deposit{value: amount}();

        // read new balance
        uint newBal = c.balances(address(this));

        // the invariant: newBal == oldBal + amount
        assert(newBal == oldBal + amount);
    }

    // allow receiving ETH so the test contract can forward it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // caller's recorded balance before
        uint before_caller = c.balances(address(this));
        // tx.origin's recorded balance before
        uint before_origin = c.balances(tx.origin);
        c.Deposit{value: amount}();
        uint after_caller = c.balances(address(this));
        uint after_origin = c.balances(tx.origin);
        // General rule: only the caller's recorded balance increases by amount; tx.origin's recorded balance remains unchanged
        assert(after_caller == before_caller + amount && after_origin == before_origin);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry test driving contract c: one depositor sends value 'amt'.
    // Asserts that balances(depositor) equals prior balance + amt.
    function check_deposit(address payable depositor, uint256 amt) public payable {
        // ensure this contract has enough ETH to forward
        require(address(this).balance >= amt, "insufficient balance to forward");

        // read prior balance
        uint256 before = c.balances(depositor);

        // perform deposit from this contract on behalf of depositor by calling c with .call as msg.sender must be depositor
        // We cannot make c see msg.sender as 'depositor' unless depositor is this contract.
        // So require depositor == address(this) to make the test valid: the caller of c.Deposit must be this contract.
        require(depositor == address(this), "depositor must be this contract for call to originate from here");

        // perform the deposit: this contract calls c.Deposit sending amt
        c.Deposit{value: amt}();

        // read after balance
        uint256 after = c.balances(depositor);

        // invariant: balance increased by exactly amt
        assert(after == before + amt);
    }

    // allow this contract to receive ETH to fund deposits
    receive() external payable {}
}

