contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint before = c.balances(address(this));
        c.Deposit{value: amount}();
        uint after = c.balances(address(this));
        // The recorded increase must equal the sent amount
        assert(after - before == amount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single externally callable test function
    function run(uint setVal, uint depositAmt, uint collectAmt) external payable {
        // preconditions for meaningful scenario
        require(setVal > 0, "setVal>0");
        require(depositAmt >= collectAmt, "deposit covers collect");
        // ensure this contract has enough ether to forward deposit
        require(address(this).balance >= depositAmt, "have funds");

        // set MinSum to the provided value
        c.SetMinSum(setVal);
        // lock initialization so SetMinSum cannot be changed later
        c.Initialized();

        // make a deposit of depositAmt
        c.Deposit{value: depositAmt}();

        // try to collect collectAmt
        c.Collect(collectAmt);

        // Observed rule: if depositAmt >= setVal then the collectAmt input (which we required <= depositAmt)
        // should be collectible when collectAmt == setVal. For the original contract this holds when collectAmt == setVal.
        // For the mutant doubling SetMinSum it would require deposit >= (setVal*2) instead.
        assert(!(depositAmt >= setVal) || collectAmt >= 0 && depositAmt >= setVal);
    }

    // allow funding this contract for deposits
    receive() external payable {}
}
